package packet

import (
	"bytes"
	"encoding/hex"
	"reflect"
	"testing"

	"github.com/sandertv/gophertunnel/minecraft/protocol"
)

// Fixtures were generated by encodePayload in the original LunaX.phar,
// vendor/axolotl-pm/bedrock-protocol/src/SetScorePacket.php (protocol 2193).
func TestSetScoreMatchesOriginalPMMPBytes(t *testing.T) {
	for _, tc := range []struct {
		name, wire string
		entry      protocol.ScoreboardEntry
	}{
		{"fake", "0103106368616e676566616b65706c61796572d20f0a496e666f506c7567696e0e0000000448503735", protocol.ScoreboardEntry{EntryID: 1001, ObjectiveName: "InfoPlugin", Score: 14, IdentityType: protocol.ScoreboardIdentityFakePlayer, DisplayName: "HP75"}},
		{"remove", "01000672656d6f7665d20f010a496e666f506c7567696e", protocol.ScoreboardEntry{EntryID: 1001, ObjectiveName: "InfoPlugin", IdentityType: protocol.ScoreboardIdentityRemove}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			want, err := hex.DecodeString(tc.wire)
			if err != nil {
				t.Fatal(err)
			}
			var buf bytes.Buffer
			pk := SetScore{Entries: []protocol.ScoreboardEntry{tc.entry}}
			pk.Marshal(protocol.NewWriter(&buf, 0))
			if !bytes.Equal(buf.Bytes(), want) {
				t.Fatalf("wire mismatch: %x != %x", buf.Bytes(), want)
			}
			var decoded SetScore
			decoded.Marshal(protocol.NewReader(bytes.NewBuffer(want), 0, true))
			if !reflect.DeepEqual(decoded.Entries, pk.Entries) {
				t.Fatalf("decode mismatch: %#v", decoded.Entries)
			}
		})
	}
}
